{
  "headline": "FDA's records trace our supply to a plant classified OAI 3109 days before the posting",
  "headline_cites": ["E5", "D3"],
  "sentences": [
    {
      "text": "The label for pegfilgrastim NDC 70121162701 names Kashiv BioSciences, LLC as the manufacturing plant.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspection 1038740 of that plant ended on 2018-01-26 and was classified OAI, with the classification known to FDA on 2018-02-16.",
      "cites": ["E5"]
    },
    {
      "text": "That OAI classification occurred 3109 days before the shortage posting date of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "A later inspection 1241763 ended on 2024-06-14 and was classified VAI, known to FDA on 2024-08-16.",
      "cites": ["E6"]
    },
    {
      "text": "Corvale East holds 41 units with 15 days on hand at current use, while Corvale General holds 158 units with 28 days on hand.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The best option by rule is to buy from Accord BioPharma, Inc., which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["E8"]
    }
  ]
}
